('99020210-d2f4-4670-a685-3c7e59ce3873', 'yield-scanner', 'Yield scanner', 'defi', 'Ranks Solana lending and LP yields by a simple net figure after fees. You choose where funds go.', 'medium', 'stub:echo', true, false, 'hosted', 'Core', null, 'Which USDC markets should I compare?'),
('9a20b70c-15bb-4c39-a9ef-15e31d671eec', 'lp-range-monitor', 'LP range monitor + alerts', 'defi', 'Watches a concentrated-liquidity position and flags when price leaves the range. It never rebalances.', 'medium', 'stub:echo', true, false, 'hosted', 'Core', null, 'Pool, range, and the wallet to watch.'),
('93469763-402e-421d-a47f-e4c23505bd27', 'liquidation-alerts', 'Liquidation / health-factor alerts', 'defi', 'Warns when a lending position''s health factor is getting close to liquidation.', 'high', 'stub:echo', true, false, 'hosted', 'Lite', null, 'Market and the wallet to watch.'),
('91493c62-0c98-4378-a591-72b45d1b7ef0', 'dca-executor', 'DCA executor (user-signed)', 'defi', 'Builds a dollar-cost-average swap for you to approve in your wallet. It cannot sign and it never holds your keys.', 'high', 'stub:echo', true, true, 'hosted', 'Pro', null, 'Asset, USDC amount, and how often.'),
('44c02867-868b-496c-a36f-083d3d31f2c7', 'portfolio-pnl', 'Portfolio + PnL tracker', 'defi', 'Reads public balances and estimates cost basis and unrealised PnL. Read-only.', 'low', 'stub:echo', true, false, 'hosted', 'Lite', null, 'Paste the wallet address to summarise.'),
('8d73043e-1d4c-41b3-a7af-05eef5a5c346', 'stablecoin-rotator', 'Stablecoin yield rotator (suggests, user signs)', 'defi', 'Suggests a stablecoin yield move and builds the transaction. Nothing moves until you sign.', 'high', 'stub:echo', true, true, 'hosted', 'Pro', null, 'Current stablecoin and the amount.'),
('645d1338-a43e-4e98-a8d4-145bb36deac9', 'points-tracker', 'Points / airdrop tracker', 'defi', 'Lists points and airdrop campaigns for wallets you choose. It does not claim or bridge.', 'medium', 'stub:echo', true, false, 'hosted', 'Lite', null, 'Wallet address to check.'),
('3942ebe8-e797-4d71-adea-bed14d14e915', 'node-uptime', 'Node uptime monitor', 'depin', 'Checks whether your DePIN nodes are answering and how long they have been quiet.', 'low', 'stub:echo', true, false, 'hosted', 'Lite', null, 'Node id or URL to check.'),
('9dd9198b-73a1-4671-aa47-cd9b8f67eeda', 'rewards-tracker', 'Rewards tracker + claim reminders', 'depin', 'Totals accrued DePIN rewards and reminds you when a claim window is open. You claim yourself.', 'low', 'stub:echo', true, false, 'hosted', 'Lite', null, 'Network and wallet address.'),
('d6e3d467-469a-4e1b-a07a-05faefa1e5d4', 'coverage-analyser', 'Coverage / earnings analyser', 'depin', 'Compares node earnings with coverage so you can see which locations are paying.', 'low', 'stub:echo', true, false, 'hosted', 'Core', null, 'Network and the region you operate in.'),
('9084ffdf-038b-4460-af4f-5db9a29d5166', 'depin-analytics', 'DePIN token + revenue analytics', 'depin', 'Summarises token emissions, protocol revenue, and payout trends for a DePIN network.', 'medium', 'stub:echo', true, false, 'hosted', 'Core', null, 'Which network should I summarise?'),
('793abf22-7bb8-4d11-a037-d7e38280194d', 'hardware-roi', 'Hardware ROI planner', 'depin', 'A one-off workbook for estimating hardware payback from assumptions you type in. Not a forecast.', 'low', 'kit:local', true, false, 'kit', 'Core', null, 'Hardware cost and expected monthly rewards.'),
('32e8c5b6-04ca-4a62-a83c-ae52530a19d8', 'rug-checker', 'Rug / risk checker', 'memecoins', 'Scores a mint for authorities, liquidity lock, and holder concentration. Three free checks a day, or a 30-day pass.', 'high', 'stub:echo', true, false, 'hosted', 'Lite', 3, 'Paste a Solana mint address.'),
('bd297d54-c465-41c4-ad20-5d172d98322d', 'launch-scanner', 'New-launch scanner', 'memecoins', 'Lists newly created mints that pass a basic liquidity filter. Discovery only, not a buy list.', 'high', 'stub:echo', true, false, 'hosted', 'Core', null, 'How far back should I look?'),
('0c1c1295-50e9-4212-afb8-4939a5e4deac', 'holder-watch', 'Holder concentration + dev-wallet watch', 'memecoins', 'Shows top holders and watches wallets you mark as the deployer. It does not trade.', 'high', 'stub:echo', true, false, 'hosted', 'Core', null, 'Mint address and the deployer wallet.'),
('974b9cc6-ba9a-49d2-ad39-3db1afa1cfb1', 'narrative-tracker', 'Social / narrative tracker', 'memecoins', 'Groups public chatter around a mint into themes. Sentiment is not a buy signal.', 'medium', 'stub:echo', true, false, 'hosted', 'Core', null, 'Mint or ticker to track.'),
('c252a0bf-cf66-4dc2-a2c4-41e715abbba4', 'snipe-alerts', 'Snipe alerts (signals only, no auto-buy)', 'memecoins', 'Sends timing signals around new pools. It will not buy, sell, or submit a swap.', 'high', 'stub:echo', true, false, 'hosted', 'Pro', null, 'Which launch window should I watch?'),
('d4280eea-b555-4bf7-ae29-b0817bd0f976', 'launch-assistant', 'Launch assistant', 'memecoins', 'A one-off checklist and script outline for a launch you run yourself. It does not deploy anything.', 'high', 'kit:local', true, false, 'kit', 'Pro', null, 'Token name and supply you are planning.'),
('03cf51dd-5e95-44aa-af5b-b84fdea9ff49', 'smart-wallet-tracker', 'Smart-wallet tracker', 'copy', 'Follows wallets you label and summarises their recent swaps. Read-only.', 'medium', 'stub:echo', true, false, 'hosted', 'Core', null, 'Wallet address to follow.'),
('4ba54d4f-b1f5-4b43-ad0f-0eca7427f9fd', 'whale-alerts', 'Whale alerts', 'copy', 'Notifies you when a watched wallet moves more than the size you set.', 'medium', 'stub:echo', true, false, 'hosted', 'Lite', null, 'Wallet and the size threshold.'),
('48876ddd-ea9e-4e1f-aa3b-29aa471bbbbd', 'copy-trade-assistant', 'Copy-trade assistant (confirm every trade)', 'copy', 'Drafts a copy of a watched trade for you to confirm. Every trade needs your signature. Nothing runs silently.', 'high', 'stub:echo', true, true, 'hosted', 'Pro', null, 'Wallet to mirror and the max USDC size.'),
('10e23cb7-7c25-4399-aae4-2d44115e59c0', 'leaderboard-analytics', 'Trader leaderboard analytics', 'copy', 'Ranks public wallets over a simple realised-PnL window. Past results are not future results.', 'medium', 'stub:echo', true, false, 'hosted', 'Core', null, 'Window length, such as 7 days.'),
('12f13e43-b5e3-4560-a77f-c6d471c4d00b', 'risk-guard', 'Risk guard (stop-loss suggestions)', 'copy', 'Suggests stop levels from the risk you state. It does not place orders.', 'high', 'stub:echo', true, false, 'hosted', 'Core', null, 'Position and how much you can lose.'),
('684f8c32-17c3-4d6b-a89f-d830e7da69e9', 'agent-kit-starter', 'Solana Agent Kit starter', 'dev', 'A starter pack for a Solana agent: layout, signing notes, and a devnet script you run yourself.', 'low', 'kit:local', true, false, 'kit', 'Pro', null, 'What should the agent do?'),
('743bf9fc-20c5-49b6-a2bd-c70e78e2dc35', 'x402-paywall-kit', 'x402 paywall kit', 'dev', 'A reference pack describing an HTTP 402 paywall in front of an agent. Soda does not meter pay-per-call.', 'low', 'kit:local', true, false, 'kit', 'Pro', null, 'Which route should the paywall cover?'),
('ee8b369a-6b94-4945-a024-075d712cb1f9', 'anchor-review', 'Anchor program review assistant', 'dev', 'Reads an Anchor program you paste and lists common safety issues. A second pair of eyes, not an audit.', 'medium', 'stub:echo', true, false, 'hosted', 'Pro', null, 'Paste the instruction handler you want read.'),
('37d1a33a-eeab-4e76-a97c-816ff9116951', 'tx-debugger', 'Tx / RPC debugger', 'dev', 'Explains a transaction signature or RPC error in plain language.', 'low', 'stub:echo', true, false, 'hosted', 'Core', null, 'Paste a signature or the RPC error.'),
('10a9c5f9-765e-4692-a966-4ee17337e3a2', 'launch-script-pack', 'Token + launch script pack', 'dev', 'Scripts and notes for creating a token on devnet. You run them. They do not target mainnet.', 'medium', 'kit:local', true, false, 'kit', 'Core', null, 'Token name, symbol, and decimals.'),
('f6216794-855c-4a48-a897-1412302958e8', 'mcp-server-pack', 'Solana MCP server pack', 'dev', 'A starter Model Context Protocol server with read-only Solana RPC helpers.', 'low', 'kit:local', true, false, 'kit', 'Pro', null, 'Which read-only RPC methods do you need?')
